I:3.2.statement_prefix:
\begin{proposition}\label{fam:src:A.1.2}\label{fam:st:A.1.2}
The normalized base change $N_j\times_{D_j}\Delta_j\to\Delta_j$, $t_j=s_j^{m_j}$, is the original smooth torus family $J'_j$. The maps $E_1\times F_1\to S_1$ and $E_2\times F_2\to S_2$ described below are finite etale covers of degrees $9$ and $8$.
\end{proposition}

I:3.4.statement_prefix:
\begin{proposition}\label{fam:src:A.3.1}\label{fam:st:A.3.1}
For each $n\in2\mathbb Z$ there is a biholomorphism $F_{n,c}:X_c\to X_{c+n}$, holomorphic jointly in $c$, with $F_{2h,c+2k}F_{2k,c}=F_{2(h+k),c}$. The quotient family over $0<|w|<e^{-\pi M}$, $w=e^{-\pi ic}$, is proper and holomorphic, with pairwise non-biholomorphic fibres.
\end{proposition}

I:4.3.statement_prefix:
\begin{proposition}\label{fam:src:B.1.3}\label{fam:st:B.1.3}
For the original affine logarithm $\mu$, we have $\wp_\tau(\mu)=0$ identically. Equivalently the generator $P=[\mu]$ of \ref{fam:src:B.1.1} is one of the two sections $P_*=(0,\sqrt2t^2(t-1))$ and $-P_*$. This assertion does not use a numerical evaluation of $\mu$ or of $\beta$.
\end{proposition}

I:4.4.statement_prefix:
\begin{proposition}\label{fam:src:B.1.4}\label{fam:st:B.1.4}
The line-bundle comparison of the period family with Engel's family over $B^\circ$ transports its inverse period lift to a global section of $\operatorname{Hom}(t_{6P}^*M_S,M_S)$ with divisor $F_\infty$. Take this transported section for $c=0$ as the reference linearization. Then $\lambda_0=1$ exactly and $u=e^{-2\pi ic}=w^2$. For another independently fixed reference the precise constant is its scalar ratio with this section. With the cusp branch fixed in Part C and $f_{\rm sc}/t\to i\sqrt3/\pi$, the section is $P=(0,-\sqrt2t^2(t-1))$.
\end{proposition}

I:4.7.statement_prefix:
\begin{proposition}[counterexample, with corrected family]\label{fam:src:B.2.3}\label{fam:st:B.2.3}
The assertion in \cite[Remark 8.1]{Engel2026} of a global proper family over the original punctured $u$-disc for fixed sphere logarithmic data requires a double-cover qualification. The retained family with such data does not descend through $u=w^2$. It does give a proper holomorphic family on each simply connected $u$-open set, and a global proper family over the punctured $w$-disc as in \ref{fam:src:A.3.1}.
\end{proposition}

I:4.9.statement_prefix:
\begin{proposition}\label{fam:src:B.4.1}\label{fam:st:B.4.1}
For each member of the retained $(3,4)$ family, $\operatorname{Aut}(X_c)$, including all its components, is $\mathbb C/\mathbb Z\simeq\mathbb C^*$. Its action on the ordinary fibres is $\zeta\mapsto\zeta+be$, and the exponential group isomorphism is $b\mapsto e^{2\pi ib}$.
\end{proposition}

I:6.2.statement_prefix:
\begin{proposition}\label{fam:src:D.1.2}\label{fam:st:D.1.2}
The locus on \(B^\circ\) where \(P(t)\) is torsion is countable and dense.
Every fibre over this locus is an abelian surface. The divisor on the
smooth base cut out by \(6kP=O\) has degree \(3k^2-1\), including local
intersection multiplicity, for every positive integer \(k\).
\end{proposition}

I:6.3.statement_prefix:
\begin{theorem}[counterexample]\label{fam:src:D.1.3}\label{fam:st:D.1.3}
The proposed assertion that \emph{existence of a surjection onto the
specified \(E_t\) with elliptic kernel} is equivalent to \(6P(t)=O\)
is false. It remains true for the specified projection in \ref{fam:src:D.1.1}.
\end{theorem}

I:6.8.statement_prefix:
\begin{proposition}\label{fam:src:D.2.1}\label{fam:st:D.2.1}
For a standard-twist member \(X_c\) with underlying manifold \(S^6\),
every compact irreducible complex curve lies in one fibre of \(f\), and
every compact irreducible complex surface is one of the reduced fibres.
\end{proposition}

I:7.5.statement_prefix:
\begin{proposition}\label{fam:src:F.2.3}\label{fam:st:F.2.3}
The positive sign region admits the global period chart
\[
 \mathcal O_+=\left\{
 (\tau,\mu,\beta)\in\mathbb C^3:
 \operatorname{Im}\tau>0,\quad
 \operatorname{Im}\beta-\frac{6(\operatorname{Im}\mu)^2}
 {\operatorname{Im}\tau}<0\right\},
\]
represented by the matrix $\Pi$ in the stated problem.  In this chart,
\begin{equation}\label{fam:eq:F-qD}
 q_e(J)=-\frac6D.
\end{equation}
Every admissible period $\Pi_c(z)$ belongs to $\mathcal O_+$, for every
admissible $c$.  Thus this single maximal proper-action open set contains
all the period images in question.
\end{proposition}

I:8.2.statement_prefix:
\begin{proposition}[Local freeness and the determinant line]\label{inv:A1.1}
Both $\mathcal A$ and $\mathcal E$ are locally free, of ranks three and
two.  The vertical vector $\xi=\partial/\partial\zeta_2$ is nowhere
zero as a section of $\mathcal E^\vee$.  There is an exact sequence
of holomorphic vector bundles
\begin{equation}\label{inv:eq:A-E-line}
0\longrightarrow N\longrightarrow\mathcal E
 \xrightarrow{\langle\cdot,\xi\rangle}\OO_X\longrightarrow0,
\qquad N=\det\mathcal E=\omega_f(-2S_1-3S_2).
\end{equation}
\end{proposition}

I:8.3.statement_prefix:
\begin{proposition}[The logarithmic direct images by vertical twisting and duality]\label{inv:A1.2}\label{wb:prop:log-relative-direct-images}
One has, as holomorphic vector bundles on $B$,
\[
\begin{array}{c|ccc}
q&0&1&2\\\hline
R^qf_*\mathcal E&\OO\oplus\OO(-1)&
 \OO^2\oplus\OO(-1)^2&\OO\oplus\OO(-1).
\end{array}
\]
They commute with base change to every full scheme fibre.
\end{proposition}

I:8.4.statement_prefix:
\begin{proposition}[All absolute cotangent direct images]\label{inv:A1.3}\label{wb:prop:absolute-cotangent-direct-images}
For every admissible $c$, the six direct images are
\begin{equation}\label{inv:eq:A-absolute-table}
\begin{array}{c|cc}
q&R^qf_*\Omega_X^1&R^qf_*\Omega_X^2\\\hline
0&\OO(-2)&\OO(-2)\oplus\OO(-1)\\
1&\OO\oplus\OO(-1)^2&\OO(-2)\oplus\OO(-1)^2\\
2&\OO\oplus\OO(-1)&\OO.
\end{array}
\end{equation}
In particular every listed sheaf is torsion-free.
\end{proposition}

