Let $\chi=(\tau-i)/(\tau+i)$. On
$0<|\chi|\le2-\sqrt3$, the invariant $F$ satisfies $|F|<1$.
At the two equianharmonic points on the boundary its continuous
value is $3/4$.
\end{proposition}

I:22.9.statement_prefix:
\begin{corollary}\label{push:src:D.3.2}
There is no path-independent limiting group at the boundary even
when \(c_n\to c_*\) from the admissible side. At \(h_n=0\) and
\(c_n=c_*-i\epsilon_n\), all of \(L_a\) survives, giving a
three-dimensional real torus if \(a\) is rational and a
two-dimensional real torus if \(a\) is irrational. Other admissible
paths give a point. The fixed-boundary Hausdorff reflection of \ref{push:src:D.2.3}
therefore cannot be identified with all pointed fibre limits.
\end{corollary}

I:23.6.statement_prefix:
\begin{proposition}[separation in irreducible analytic families]\label{push:src:E.2.3}
Suppose a proper holomorphic submersion over a connected
irreducible reduced complex base has two fibres of the type
in \ref{push:src:E.2.1}.  Then their multiplicity pairs agree, even if some
other fibres have not been constructed by this method.
For these members the asymptotic number
\[
 s(X)=\lim_{r\to\infty}
 \frac{h^0(X,K_X^r)-h^0(X,K_X^{-r})}{r}
 =\frac1{12}-\frac1{3k}-\frac1{4l}
\]
recovers the ordered multiplicity pair uniquely.
\end{proposition}

I:23.11.statement_prefix:
\begin{theorem}[quantitative local maximum]\label{push:src:E.4.2}
If $|\tau-i|\leq3/20000$ and $\wp_\tau(z)=0$, then
$\mathcal N(z,\tau)\leq\sqrt2$, with equality precisely at
$\tau=i$. The proof uses the explicit constants below.
\end{theorem}

I:B.1.statement_prefix:
\begin{lemma}[simultaneous elliptic-orientation normalization]
\label{wb:lem:triangle-generator-orientations}
\ The generators may, and henceforth do, satisfy
\begin{equation}
 g_1'(z_1)=e^{-2\pi i/3},\qquad
 g_2'(z_2)=e^{-2\pi i/4}=-i,
\label{wb:eq:triangle-generator-derivatives}
\end{equation}
while \(g_0=(g_1g_2)^{-1}\) remains parabolic.  More precisely, the Cayley
coordinates
\begin{equation}
 s_j(z)=\frac{z-z_j}{z-\bar z_j}
\label{wb:eq:triangle-cayley-coordinates}
\end{equation}
obey
\begin{equation}
 s_1\circ g_1=e^{-2\pi i/3}s_1,
 \qquad
 s_2\circ g_2=-is_2.
\label{wb:eq:triangle-linearizing-identities}
\end{equation}
The two signs in \cref{wb:eq:triangle-generator-derivatives} are

I:D.3.statement_prefix:
\begin{lemma}[the primitive first transgression]
\label{mapsI:top:lem:first-transgression}
\ For the constructed map and the based meridians of
\cref{mapsI:top:prop:geometric-pi1}, one may orient \(\omega\) so that
\[
 d_2^{0,1}(12\gamma)=\omega.
\tag{IL.5.18}
\]
\end{lemma}

I:D.4.statement_prefix:
\begin{lemma}[the higher transgressions]
\label{mapsI:top:lem:higher-transgressions}
\ In the integral Leray spectral sequence of the constructed map,
\[
 d_2^{0,2}(2q)=\omega[\delta],
 \qquad
 d_2^{0,3}(2\gamma uw)=\omega[\gamma\delta].
\tag{IL.5.22}
\]
\end{lemma}

I:D.5.statement_prefix:
\begin{theorem}[integral cohomology in low degrees]
\label{mapsI:top:thm:h2-vanishing}
\ For the constructed holomorphic map,
\[
 H^1(X;\mathbb Z)=H^2(X;\mathbb Z)=H^3(X;\mathbb Z)=0,
 \qquad H_2(X;\mathbb Z)=0.
\tag{IL.5.23}
\]
\end{theorem}

I:D.7.statement_prefix:
\begin{corollary}[topology and the third Chern number]
\label{mapsI:top:cor:candidate-sphere}
\ The underlying smooth manifold of the constructed threefold is
diffeomorphic to the standard six-sphere, and
\[
 \langle c_3(T_X),[X]\rangle=2.
\tag{IL.5.25}
\]
\end{corollary}

I:E.17.statement_prefix:
\begin{theorem}[sphere recognition from the exact inputs]
\label{mapsI:top:thm:sphere-recognition}
\ Let $X$ be a smooth, closed, connected six-manifold.  If
\[
\pi_1(X)=0,\qquad
H_k(X;\mathbb Z)\cong
\begin{cases}
\mathbb Z,&k=0,6,\\
0,&1\le k\le5,
\end{cases}
\tag{TM.4.5}
\]
then $X$ is diffeomorphic to the standard $S^6$.
\end{theorem}

I:F.1.statement_prefix:
\begin{lemma}[homotopy invariance]
\label{mapsI:chain:lemma:1.1}
Homotopic maps of pairs induce the same homology and cohomology maps, with every coefficient group.
\end{lemma}

I:F.3.statement_prefix:
\begin{corollary}[excision]
\label{mapsI:chain:corollary:2.2}
If \(Z\subset A\subset X\) and \(\overline Z\subset\operatorname{int}_X A\), the inclusion
\((X\setminus Z,A\setminus Z)\to(X,A)\)
induces homology and cohomology isomorphisms with every coefficient group.
\end{corollary}

I:F.4.statement_prefix:
\begin{lemma}[product chain equivalence]
\label{mapsI:chain:lemma:4.1}
\leavevmode\par
The two maps are inverse up to natural chain homotopies, preserving products of subspaces.
\end{lemma}

I:G.1.statement_prefix:
\begin{theorem}
\label{mapsI:cw:hurewicz-theorem-result}
Under \eqref{mapsI:cw:eq:3.2}, \(h\) is an isomorphism and
