II:16.8.statement_prefix:
\begin{proposition}[no horizontal divisor when all fibres are irreducible]\label{push:src:E.2.9}
Let $X$ be a compact complex threefold diffeomorphic to $S^6$,
and let $f:X\to\mathbb P^1$ be a surjective holomorphic map
with connected fibres.  If every reduced fibre is irreducible,
then $X$ has no horizontal prime divisor for $f$.
\end{proposition}

II:17.1.statement_prefix:
\begin{proposition}[Credited re-derivation: stability of the pencil for the standard family]\label{inv:E1.1}
Every sufficiently small deformation of the standard $X_c$ carries a
holomorphic map to $\Pone$ with general fibre a complex two-torus. Its
complete anticanonical system $|-2K|$ is basepoint-free of dimension one
and recovers that map, and its algebraic dimension is one.
\end{proposition}

II:17.3.statement_prefix:
\begin{proposition}[Counterexample: The universal two-vector-field bound]\label{inv:E2.4}
The assertion that every complex structure on $S^6$ has
$h^0(T)\le2$, printed in
\citet[Corollary 1.3; verified preprint p.~2]{HKP2000}
and repeated in \citet[Remarks 1.2 and 9.26]{AC2026}, is false
for the comb members.
\end{proposition}

II:A.2.statement_prefix:
\begin{proposition}[Credited re-derivation: The precise range of the normalization formula]\label{cdp:st:A.2.3}
The canonical inclusion $\eta_*\eta^*N^*\hookrightarrow K$ is an isomorphism exactly when $S$ has normal crossings outside an analytic subset of codimension at least two in $S$.
\end{proposition}

II:A.8.statement_prefix:
\begin{proposition}[Credited re-derivation: Excluded algebraic dimensions]\label{cdp:st:E3}
A positive-dimensional compact Moishezon manifold has $b_2>0$.
A compact complex manifold homeomorphic to $S^6$ has algebraic
dimension $0$ or $1$; in the latter case its algebraic reduction is
holomorphic onto $\mathbb P^1$.
\end{proposition}

II:A.9.statement_prefix:
\begin{proposition}[Credited re-derivation: Degree-one cohomological flatness over a curve]\label{cdp:st:E4}
For a proper surjective holomorphic map $g:Y\to C$ from a connected complex
manifold to a nonsingular curve with connected fibres,
$R^1g_*\mathcal O_Y$ is locally free and
$H^0(Y_c,\mathcal O_{Y_c})=\mathbb C$ for every scheme-theoretic fibre.
\end{proposition}

II:B.3.statement_prefix:
\begin{corollary}
\label{wbII:cor:normal-crossing-kernel}
If, in addition, $H^0(S,N^*_{S/X}\otimes A)=0$ and
$H^0(S,\widetilde\Omega^1_S\otimes A)=0$, then the section in
Proposition~\ref{wbII:prop:conductor} proves that $\delta_A$ in
the section-kernel isomorphism of \cref{cdp:st:A.1.1} is not injective.
\end{corollary}

