\begin{equation}
H^r(M;F)\times H^{d-r}(M;F)\to F,
\qquad (a,b)\mapsto\langle a\smile b,[M]\rangle
\label{courseIII:manifold-duality-the-diagonal-and-wu-classes.source:eq:2.2}
\end{equation}


is perfect.
\end{corollary}

III:F.4.statement_prefix:
\begin{lemma}[Local inverse and local flows]
\label{courseIII:duality:3.1}
A smooth map between open Euclidean sets with invertible derivative at a point has a smooth inverse on neighbourhoods of that point. A smooth finite-dimensional vector field has a unique local flow, smooth in time and its initial point.
\end{lemma}

III:F.5.statement_prefix:
\begin{theorem}[Tubular neighbourhood]
\label{courseIII:duality:3.2}
If \(M\subset A\) is a smooth embedded submanifold, its normal quotient bundle \(\nu=TA|_M/TM\) has a neighbourhood of its zero section diffeomorphic to an open neighbourhood of \(M\) in \(A\), fixing \(M\). The whole bundle is diffeomorphic to such a neighbourhood by a radial fibre change. If \(M\) is closed as a subset of \(A\), excision also identifies the pairs' cohomology


\begin{equation}
H^*(A,A\setminus M;R)\cong H^*(\nu,\nu\setminus M;R).
\label{courseIII:manifold-duality-the-diagonal-and-wu-classes.source:eq:3.2}
\end{equation}


\end{theorem}

III:F.6.statement_prefix:
\begin{lemma}[Compact Euclidean embedding and finite domination]
\label{courseIII:duality:3.3}
Every compact smooth manifold embeds smoothly in some finite Euclidean space and is a retract of a neighbourhood there. Its integer homology is finitely generated and vanishes in sufficiently large degrees, whether or not it is oriented.
\end{lemma}

III:F.7.statement_prefix:
\begin{theorem}[The signed diagonal formula]
\label{courseIII:duality:4.1}
Work over a field \(F\), with \(M\) oriented or with \(F=\mathbb F _2\). Choose a homogeneous basis \(b_i\) of \(H^*(M;F)\), and its cup-dual basis \(b_i^\vee\) satisfying


\[
\langle b_i\smile b_j^\vee,[M]\rangle=\delta_{ij}.
\]


Then


\begin{equation}
U=\sum_i(-1)^{|b_i|}\,b_i\times b_i^\vee.
\label{courseIII:manifold-duality-the-diagonal-and-wu-classes.source:eq:4.5}
\end{equation}


\end{theorem}

III:F.8.statement_prefix:
\begin{corollary}[Euler number and Euler characteristic]
\label{courseIII:duality:4.2}
For a closed oriented manifold,


\begin{equation}
\langle e(TM),[M]\rangle=\chi(M).
\label{courseIII:manifold-duality-the-diagonal-and-wu-classes.source:eq:4.7}
\end{equation}


For every closed manifold,


\begin{equation}
\langle w_d(TM),[M]_2\rangle\equiv\chi(M)\pmod2.
\label{courseIII:manifold-duality-the-diagonal-and-wu-classes.source:eq:4.8}
\end{equation}


\end{corollary}

III:J.1.statement_prefix:
\begin{theorem}
\label{courseIII:morse-cancellation-with-controlled-support:source-theorem-2.1}
There is a smooth function \(F\), equal to \(f\) outside a compact subset of \(U\), with no critical points in the region where the two given critical points and their connecting trajectory are changed. No new critical points occur anywhere. There is a smooth interpolation from \(f\) to \(F\), fixed outside that same region.
\end{theorem}

III:Z.1.statement_prefix:
\begin{theorem}
\label{courseIII:the-degree-six-milnor-cobar-calculation:source-theorem-1.1}
For the full Hopf algebra \eqref{courseIII:the-degree-six-milnor-cobar-calculation:eq:1.1}--\eqref{courseIII:the-degree-six-milnor-cobar-calculation:eq:1.2},

\begin{equation}
\mathcal H^{s,s+6}(H)=
 \begin{cases}
 \mathbb F _2\{[\zeta_1^4|\zeta_1^4]\},&s=2,\\
 0,&s\ne2.
 \end{cases}
 \label{courseIII:the-degree-six-milnor-cobar-calculation:eq:1.8}
\end{equation}
\end{theorem}

III:Z.2.statement_prefix:
\begin{theorem}
\label{courseIII:the-degree-six-milnor-cobar-calculation:source-theorem-6.1}
For every odd prime,

\begin{equation}
\mathcal H^{s,s+6}(H_p)=0\quad\hbox{for all }s\geq0.
 \label{courseIII:the-degree-six-milnor-cobar-calculation:eq:6.4}
\end{equation}
\end{theorem}

III:AH.1.statement_prefix:
\begin{proposition}
Choose two disjoint orientation-preserving coordinate closed discs \(D_0,D_1\subset X\). Then


\begin{equation}
C=X\setminus(\operatorname{int}D_0\cup\operatorname{int}D_1)
\label{courseIII:integral-homology-and-sphere-recognition:eq:10.1}
\end{equation}


is a simply connected smooth six-dimensional \(h\)-cobordism between its two boundary five-spheres.
\end{proposition}

III:AH.2.statement_prefix:
\begin{theorem}
There is an orientation-preserving smooth diffeomorphism \(d:S^6\to X\), with \(d\simeq g\) and \(d^{-1}\simeq h_X\) for the original maps of Paper~I, Theorem~I.1.
\end{theorem}

III:AI.1.statement_prefix:
\begin{theorem}
\label{courseIII:almost-complex-structures-and-integrability:source-theorem-9.1}
A smooth almost complex structure is induced by a complex coordinate atlas if and only if its tensor \eqref{courseIII:almost-complex-structures-and-integrability:eq:1.5} vanishes.
\end{theorem}
